-- Exact arithmetic evidence only; never promotes family quality or serving.
CREATE TABLE population_top3000_202608_202609_v1.daily_practical_quality_batch_v2(
 cohort_sha256 text NOT NULL,run_id uuid NOT NULL,first_series integer NOT NULL,last_series integer NOT NULL,
 input_versions jsonb NOT NULL,report jsonb NOT NULL,report_sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(cohort_sha256,run_id,first_series));
ALTER TABLE population_top3000_202608_202609_v1.daily_practical_quality_batch_v2 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON population_top3000_202608_202609_v1.daily_practical_quality_batch_v2 FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.daily_practical_quality_worker_v2(p_attempt uuid,p_token text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET "TimeZone"='UTC' AS $fn$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;r population_top3000_202608_202609_v1.daily_shared_run_v1%rowtype;
 s population_top3000_202608_202609_v1.daily_shared_series_v1%rowtype;v jsonb;checks jsonb:='[]';v_report jsonb;h text;first_n integer;last_n integer;prior_n integer;inputs jsonb;outputs jsonb;inserted_n integer;successor_id bigint;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.daily_shared_run_v1 WHERE run_id='19a35bfa-6023-4092-9809-3ed950871d7f';
 IF t.family_id<>'D03' OR t.stage NOT IN('DERIVE','VALIDATE') OR t.payload->>'kind' IS DISTINCT FROM 'DAILY_PRACTICAL_QUALITY_V2'
 OR t.input_versions->>'scope_sha256' IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd'
 OR t.partition_key IS DISTINCT FROM 'daily-practical-quality-v2:'||(t.input_versions->>'cohort_sha256')||':'||(t.input_versions->>'policy_sha256')
 OR t.input_versions->>'cohort_sha256' IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec'
 OR t.input_versions->>'policy_sha256' IS DISTINCT FROM '3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb'
 OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM '20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9'
 OR t.input_versions->>'daily_input_versions_sha256' IS DISTINCT FROM encode(sha256(convert_to(r.input_versions::text,'UTF8')),'hex')
 OR t.input_versions->>'daily_input_versions_sha256' IS DISTINCT FROM '6fe3d08080861b40b3d4c7cd0763a18a4fdf861d533b4a63c3164a8c1a23c539'
 OR t.input_versions->>'numeric_code_sha256' IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.daily_practical_numeric_check_v2(jsonb,jsonb)'::regprocedure),'UTF8')),'hex')
 OR t.input_versions->>'worker_code_sha256' IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.daily_practical_quality_worker_v2(uuid,text)'::regprocedure),'UTF8')),'hex')
 OR r.series_count<>13044 OR r.normalized_series<>13044 OR r.derived_series<>13044 OR r.derived_at IS NULL
 OR (SELECT budget_evidence#>>'{cohort_selection_policy,policy_sha256}' FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) IS DISTINCT FROM t.input_versions->>'policy_sha256'
 OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_membership_v1 WHERE snapshot_sha256=t.input_versions->>'cohort_sha256' AND acceptance_sha256=t.input_versions->>'membership_acceptance_sha256')
 THEN RAISE EXCEPTION 'DAILY_PRACTICAL_POLICY_COHORT_INPUT_CHANGED';END IF;
 SELECT event_id INTO successor_id FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5' AND details->>'assignment_id'='daily-practical-quality-evidence-review-v2-20261024' AND details->>'parent_assignment_event_id'='27036' AND details->>'assigned_executor'='automation:6adc2c96db348191bca7cf4eacfdac32' ORDER BY event_id DESC LIMIT 1;
 IF successor_id IS NULL THEN RAISE EXCEPTION 'DAILY_PRACTICAL_EXACT_REVIEW_SUCCESSOR_REQUIRED';END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','DAILY_PRACTICAL_POPULATION_SOURCE_SEMANTICS_REVIEW_REQUIRED','resumption_condition',jsonb_build_object('cohort_sha256',t.input_versions->>'cohort_sha256','engineering_assignment_event_id',successor_id,'arithmetic_reports_available',true,'source_series_count',13044,'selected_security_session_population_verified',false,'required',jsonb_build_array('Full-period dated instrument denominator','Regular-session close volume dollar-volume basis','Split and identity knowledge-time qualifications','Independent evidence review and unresolved outlier adjudication'),'family_accepted',false,'automatic_retry',false)); END IF;
 prior_n:=coalesce((t.checkpoint->>'last_series')::integer,0);first_n:=prior_n+1;last_n:=least(prior_n+25,13044);
 IF prior_n<0 OR prior_n>=13044 OR prior_n%25<>0 THEN RAISE EXCEPTION 'DAILY_PRACTICAL_CHECKPOINT_INVALID';END IF;
 IF prior_n>0 AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.daily_practical_quality_batch_v2 b WHERE b.cohort_sha256=t.input_versions->>'cohort_sha256' AND b.run_id=r.run_id AND b.last_series=prior_n AND b.input_versions=t.input_versions)THEN RAISE EXCEPTION 'DAILY_PRACTICAL_PRIOR_BATCH_REQUIRED';END IF;
 PERFORM population_top3000_202608_202609_v1.d02_daily_resource_guard_v2();
 FOR s IN SELECT * FROM population_top3000_202608_202609_v1.daily_shared_series_v1 WHERE run_id=r.run_id AND series_no BETWEEN first_n AND last_n ORDER BY series_no LOOP
 inputs:=population_top3000_202608_202609_v1.daily_shared_input_json_v1(r.run_id,s.series_no);outputs:=population_top3000_202608_202609_v1.daily_shared_output_json_v1(r.run_id,s.series_no);
 IF s.input_sha256 IS DISTINCT FROM sha256(convert_to(inputs::text,'UTF8')) OR s.output_sha256 IS DISTINCT FROM sha256(convert_to(outputs::text,'UTF8')) OR jsonb_array_length(inputs)<>103 OR jsonb_array_length(outputs)<>42
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(inputs)i WHERE i->>'input_record_sha256' IS DISTINCT FROM encode(sha256(convert_to((i-'input_record_sha256')::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'DAILY_PRACTICAL_SOURCE_HASH_CHANGED:%',s.series_no;END IF;
 v:=population_top3000_202608_202609_v1.daily_practical_numeric_check_v2(inputs,outputs)-'mismatch_examples';
 checks:=checks||jsonb_build_array(v||jsonb_build_object('series_no',s.series_no,'input_sha256',encode(s.input_sha256,'hex'),'output_sha256',encode(s.output_sha256,'hex')));
 END LOOP;
 IF jsonb_array_length(checks)<>last_n-first_n+1 THEN RAISE EXCEPTION 'DAILY_PRACTICAL_MISSING_SERIES';END IF;
 v_report:=jsonb_build_object('first_series',first_n,'last_series',last_n,'series_count',jsonb_array_length(checks),'source_evidence_sha256',encode(sha256(convert_to(checks::text,'UTF8')),'hex'),'counts',(SELECT jsonb_object_agg(key,total) FROM(SELECT key,sum(j.value::text::bigint) total FROM jsonb_array_elements(checks)c CROSS JOIN LATERAL jsonb_each(c)j WHERE key IN('checked_target_rows','missing_output_rows','extra_output_rows','scalar_checks','null_expectations','arithmetic_mismatches','outlier_rows','numeric_extreme_input_rows_unverified') GROUP BY key)x),'series_checks',checks,'candidate_arithmetic_only',true,'family_accepted',false,'source_semantics_accepted',false,'selected_population_complete',false);
 h:=encode(sha256(convert_to(v_report::text,'UTF8')),'hex');
 INSERT INTO population_top3000_202608_202609_v1.daily_practical_quality_batch_v2(cohort_sha256,run_id,first_series,last_series,input_versions,report,report_sha256)VALUES(t.input_versions->>'cohort_sha256',r.run_id,first_n,last_n,t.input_versions,v_report,h)ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted_n=ROW_COUNT;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.daily_practical_quality_batch_v2 b WHERE b.cohort_sha256=t.input_versions->>'cohort_sha256' AND b.run_id=r.run_id AND b.first_series=first_n AND b.last_series=last_n AND b.input_versions=t.input_versions AND b.report=v_report AND b.report_sha256=h)THEN RAISE EXCEPTION 'DAILY_PRACTICAL_REPLAY_CONFLICT';END IF;
 IF pg_total_relation_size('population_top3000_202608_202609_v1.daily_practical_quality_batch_v2')>33554432 THEN RAISE EXCEPTION 'DAILY_PRACTICAL_STORAGE_ENVELOPE';END IF;
 RETURN jsonb_build_object('state',CASE WHEN last_n=13044 THEN 'COMPLETE' ELSE 'CONTINUE' END,'checkpoint',jsonb_build_object('last_series',last_n),'commit_receipt',jsonb_build_object('commit_key','daily-practical-quality-v2:'||(t.input_versions->>'cohort_sha256')||':'||first_n||':'||last_n,'output_sha256',h,'new_committed_units',inserted_n,'immutable_output_ids',jsonb_build_array(t.input_versions->>'cohort_sha256',r.run_id,first_n,last_n),'input_versions',t.input_versions,'candidate_arithmetic_only',true,'family_accepted',false));
END;$fn$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.daily_practical_quality_worker_v2(uuid,text) FROM PUBLIC,anon,authenticated;

