CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.daily_practical_derive_route_v2(p_attempt uuid,p_token text)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;
BEGIN tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid AND payload->>'kind'='DAILY_PRACTICAL_QUALITY_V2')THEN RETURN population_top3000_202608_202609_v1.daily_practical_quality_worker_v2(p_attempt,p_token);END IF;
 RETURN population_top3000_202608_202609_v1.daily_shared_derive_admitted_v2(p_attempt,p_token);END;$f$;
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.daily_practical_validate_route_v2(p_attempt uuid,p_token text)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;
BEGIN tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid AND payload->>'kind'='DAILY_PRACTICAL_QUALITY_V2')THEN RETURN population_top3000_202608_202609_v1.daily_practical_quality_worker_v2(p_attempt,p_token);END IF;
 RETURN population_top3000_202608_202609_v1.daily_shared_quality_hold_v1(p_attempt,p_token);END;$f$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.daily_practical_derive_route_v2(uuid,text),population_top3000_202608_202609_v1.daily_practical_validate_route_v2(uuid,text)FROM PUBLIC,anon,authenticated;
DO $register$
DECLARE iv jsonb;tid uuid;a jsonb;d jsonb;
BEGIN
 SELECT details INTO STRICT a FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=27036;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5' AND details->>'assignment_id'='daily-practical-quality-evidence-review-v2-20261024')THEN RAISE EXCEPTION 'DAILY_REVIEW_ALREADY_DISPATCHED';END IF;
