BEGIN; SET LOCAL statement_timeout='45s';-- Independent bounded arithmetic checker. Uses direct numeric products and explicit
-- ordinal intervals, not daily_shared_math_v1 or its window-query implementation.
-- Equality is candidate arithmetic only: source/session/identity/knowledge evidence
-- must be assessed separately and this function never accepts a family.
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.daily_practical_numeric_check_v2(p_rows jsonb,p_values jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $fn$
DECLARE n integer;i integer;j integer;k integer;h integer;v jsonb;r jsonb;
 cs numeric[]:=ARRAY[]::numeric[];vs numeric[]:=ARRAY[]::numeric[];ds numeric[]:=ARRAY[]::numeric[];
 ac numeric[]:=ARRAY[]::numeric[];av numeric[]:=ARRAY[]::numeric[];
 anchors text[]:=ARRAY[]::text[];actions integer[]:=ARRAY[]::integer[];
 dates text[]:=ARRAY[]::text[];targets boolean[]:=ARRAY[]::boolean[];
 product numeric:=1;f numeric;c numeric;vol numeric;dv numeric;expected numeric;actual float8;
 good boolean;identity_ok boolean;action_ok boolean;aa text;
 rets numeric[];logs numeric[];vols numeric[];amis numeric[];mean_v numeric;sd_v numeric;
 expectations jsonb;fields text[]:=ARRAY['realized_log_vol_20d','annualized_log_vol_20d','annualized_simple_vol_20d','relative_volume_20d','volume_z20','daily_amihud','amihud_mean_20d'];
 checks integer:=0;mismatches integer:=0;null_checks integer:=0;outliers integer:=0;unsupported integer:=0;missing_rows integer:=0;
 details jsonb:='[]';actual_value jsonb;seen integer:=0;
BEGIN
 IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(p_values) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 103 OR jsonb_array_length(p_values)>103
 OR octet_length(p_rows::text)>524288 OR octet_length(p_values::text)>524288
 THEN RAISE EXCEPTION 'DAILY_NUMERIC_BOUNDED_ARRAYS_REQUIRED';END IF;
 n:=jsonb_array_length(p_rows);
 FOR i IN 1..n LOOP
 r:=p_rows->(i-1);
 IF r->>'ordinal' IS DISTINCT FROM i::text OR r->>'session_date' IS NULL
 OR (i>1 AND r->>'session_date'<=dates[i-1]) OR jsonb_typeof(r->'is_target') IS DISTINCT FROM 'boolean'
 THEN RAISE EXCEPTION 'DAILY_NUMERIC_ORDER_OR_TARGET_INVALID';END IF;
 f:=(r->>'split_factor')::numeric;
 IF f IS NULL OR f<=1e-20 OR f>=1e20 OR f::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'DAILY_NUMERIC_SPLIT_INVALID';END IF;
 product:=product*f;
 c:=(r->>'raw_close')::numeric;vol:=(r->>'raw_volume')::numeric;dv:=(r->>'dollar_volume')::numeric;
 IF r->>'source_count' IS DISTINCT FROM '1' OR c IS NULL OR c<1e-100 OR c>1e100 OR c::text IN('NaN','Infinity','-Infinity') THEN c:=NULL;END IF;
 IF r->>'source_count' IS DISTINCT FROM '1' OR vol IS NULL OR vol<0 OR (vol>0 AND vol<1e-100) OR vol>1e100 OR vol::text IN('NaN','Infinity','-Infinity') THEN vol:=NULL;END IF;
 IF r->>'source_count' IS DISTINCT FROM '1' OR dv IS NULL OR dv<1e-100 OR dv>1e100 OR dv::text IN('NaN','Infinity','-Infinity') THEN dv:=NULL;END IF;
 cs:=array_append(cs,c);vs:=array_append(vs,vol);ds:=array_append(ds,dv);
 -- Numeric overflow/underflow corners remain explicitly unverified, not false PASS.
 IF product<1e-120 OR product>1e120 THEN unsupported:=unsupported+1;ac:=array_append(ac,NULL);av:=array_append(av,NULL);
 ELSE ac:=array_append(ac,c*product);av:=array_append(av,vol/product);END IF;
 anchors:=array_append(anchors,nullif(r->>'identity_anchor',''));actions:=array_append(actions,(r->>'unknown_actions')::integer);
 dates:=array_append(dates,r->>'session_date');targets:=array_append(targets,(r->>'is_target')::boolean);
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_values)x GROUP BY x->>'session_date' HAVING count(*)>1) THEN RAISE EXCEPTION 'DAILY_NUMERIC_DUPLICATE_OUTPUT';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_values)x WHERE jsonb_typeof(x->'raw_returns') IS DISTINCT FROM 'array' OR jsonb_typeof(x->'adjusted_returns') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'raw_returns')<>4 OR jsonb_array_length(x->'adjusted_returns')<>4) THEN RAISE EXCEPTION 'DAILY_NUMERIC_RETURN_ARRAY_SHAPE';END IF;
 FOR i IN 1..n LOOP
 IF NOT targets[i] THEN CONTINUE;END IF;
 SELECT value INTO v FROM jsonb_array_elements(p_values) WHERE value->>'session_date'=dates[i];
 IF v IS NULL THEN missing_rows:=missing_rows+1;CONTINUE;END IF;seen:=seen+1;
 expectations:='{}';
 FOR k IN 1..4 LOOP
 h:=(ARRAY[1,5,20,60])[k];good:=i>h;identity_ok:=true;action_ok:=true;aa:=NULL;
 IF good THEN FOR j IN (i-h)..i LOOP
 IF cs[j] IS NULL THEN good:=false;END IF;
 IF anchors[j] IS NOT NULL THEN IF aa IS NOT NULL AND aa<>anchors[j] THEN identity_ok:=false;END IF;aa:=anchors[j];END IF;
 IF j>i-h AND actions[j] IS DISTINCT FROM 0 THEN action_ok:=false;END IF;
 END LOOP;END IF;
 expected:=NULL;IF good AND identity_ok THEN expected:=cs[i]/cs[i-h]-1;END IF;
 expectations:=expectations||jsonb_build_object('raw_'||k,expected);
 expected:=NULL;IF good AND identity_ok AND action_ok AND ac[i] IS NOT NULL AND ac[i-h]>0 THEN expected:=ac[i]/ac[i-h]-1;END IF;
 expectations:=expectations||jsonb_build_object('adjusted_'||k,expected);
 END LOOP;
 rets:=ARRAY[]::numeric[];logs:=ARRAY[]::numeric[];vols:=ARRAY[]::numeric[];amis:=ARRAY[]::numeric[];
 good:=i>20;identity_ok:=true;action_ok:=true;aa:=NULL;
 IF good THEN FOR j IN (i-20)..i LOOP
 IF cs[j] IS NULL THEN good:=false;END IF;
 IF anchors[j] IS NOT NULL THEN IF aa IS NOT NULL AND aa<>anchors[j] THEN identity_ok:=false;END IF;aa:=anchors[j];END IF;
 IF j>i-20 AND actions[j] IS DISTINCT FROM 0 THEN action_ok:=false;END IF;
 IF j<i AND av[j] IS NOT NULL THEN vols:=array_append(vols,av[j]);END IF;
 IF j>i-20 AND ac[j]>0 AND ac[j-1]>0 AND actions[j]=0 THEN
 expected:=ac[j]/ac[j-1]-1;rets:=array_append(rets,expected);logs:=array_append(logs,ln(ac[j]/ac[j-1]));
 IF ds[j]>0 THEN amis:=array_append(amis,abs(expected)/ds[j]);END IF;
 END IF;
 END LOOP;END IF;
 expectations:=expectations||jsonb_build_object('realized_log_vol_20d',NULL,'annualized_log_vol_20d',NULL,'annualized_simple_vol_20d',NULL,'relative_volume_20d',NULL,'volume_z20',NULL,'daily_amihud',NULL,'amihud_mean_20d',NULL);
 IF good AND identity_ok AND action_ok AND cardinality(rets)=20 THEN
 SELECT stddev_samp(x) INTO expected FROM unnest(logs)x;
 expectations:=expectations||jsonb_build_object('realized_log_vol_20d',expected,'annualized_log_vol_20d',expected*sqrt(252::numeric));
 SELECT stddev_samp(x)*sqrt(252::numeric) INTO expected FROM unnest(rets)x;
 expectations:=expectations||jsonb_build_object('annualized_simple_vol_20d',expected);
 END IF;
 IF i>20 AND identity_ok AND action_ok AND cardinality(vols)=20 THEN
 SELECT avg(x),stddev_samp(x) INTO mean_v,sd_v FROM unnest(vols)x;
 IF mean_v>0 THEN expectations:=expectations||jsonb_build_object('relative_volume_20d',av[i]/mean_v);END IF;
 IF sd_v>0 THEN expectations:=expectations||jsonb_build_object('volume_z20',(av[i]-mean_v)/sd_v);END IF;
 END IF;
 IF good AND identity_ok AND action_ok AND cardinality(amis)=20 THEN
 SELECT avg(x) INTO expected FROM unnest(amis)x;expectations:=expectations||jsonb_build_object('amihud_mean_20d',expected);END IF;
 IF (expectations->>'adjusted_1') IS NOT NULL AND ds[i]>0 THEN expectations:=expectations||jsonb_build_object('daily_amihud',abs((expectations->>'adjusted_1')::numeric)/ds[i]);END IF;
 FOR aa,actual_value IN SELECT key,value FROM jsonb_each(expectations) LOOP
 expected:=CASE WHEN actual_value='null'::jsonb THEN NULL ELSE actual_value::text::numeric END;
 IF aa LIKE 'raw_%' THEN actual_value:=v->'raw_returns'->(right(aa,1)::integer-1);
 ELSIF aa LIKE 'adjusted_%' THEN actual_value:=v->'adjusted_returns'->(right(aa,1)::integer-1);
 ELSE actual_value:=v->aa;END IF;
 actual:=CASE WHEN actual_value IS NULL OR actual_value='null'::jsonb THEN NULL ELSE actual_value::text::float8 END;
 checks:=checks+1;IF expected IS NULL THEN null_checks:=null_checks+1;END IF;
 IF actual::text IN('NaN','Infinity','-Infinity') OR (expected IS NULL)<>(actual IS NULL)
 OR (expected IS NOT NULL AND actual IS NOT NULL AND abs(actual::numeric-expected)>1e-10+abs(expected)*1e-9)
 THEN mismatches:=mismatches+1;
 IF jsonb_array_length(details)<10 THEN details:=details||jsonb_build_array(jsonb_build_object('date',dates[i],'field',aa,'expected',expected,'actual',actual));END IF;END IF;
 END LOOP;
 IF abs((expectations->>'adjusted_1')::numeric)>1 OR abs((expectations->>'volume_z20')::numeric)>10 THEN outliers:=outliers+1;END IF;
 END LOOP;
 RETURN jsonb_build_object('checked_target_rows',seen,'missing_output_rows',missing_rows,'extra_output_rows',jsonb_array_length(p_values)-seen,'scalar_checks',checks,'null_expectations',null_checks,'arithmetic_mismatches',mismatches,'outlier_rows',outliers,'numeric_extreme_input_rows_unverified',unsupported,'mismatch_examples',details,'absolute_tolerance',1e-10,'relative_tolerance',1e-9,'family_accepted',false,'source_semantics_accepted',false,'method','EXPLICIT_ORDINAL_INTERVALS_DIRECT_NUMERIC_SPLIT_PRODUCTS');
END;$fn$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.daily_practical_numeric_check_v2(jsonb,jsonb) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.daily_practical_numeric_v2(p_run uuid,p_series integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $fn$
DECLARE r jsonb;i jsonb;o jsonb;s population_top3000_202608_202609_v1.daily_shared_series_v1%rowtype;
BEGIN
 IF p_run IS DISTINCT FROM '19a35bfa-6023-4092-9809-3ed950871d7f'::uuid OR p_series NOT BETWEEN 1 AND 13044 OR p_series IS NULL THEN RAISE EXCEPTION 'DAILY_NUMERIC_EXACT_RUN_AND_SERIES_REQUIRED';END IF;
 SELECT * INTO STRICT s FROM population_top3000_202608_202609_v1.daily_shared_series_v1 WHERE run_id=p_run AND series_no=p_series;
 i:=population_top3000_202608_202609_v1.daily_shared_input_json_v1(p_run,p_series);
 o:=population_top3000_202608_202609_v1.daily_shared_output_json_v1(p_run,p_series);
 IF i IS NULL OR o IS NULL THEN RAISE EXCEPTION 'DAILY_NUMERIC_MISSING_RETAINED_SERIES';END IF;
 r:=population_top3000_202608_202609_v1.daily_practical_numeric_check_v2(i,o);
 -- Value-bearing mismatch examples stay private within direct caller output only.
 RETURN (r-'mismatch_examples')||jsonb_build_object('run_id',p_run,'series_no',p_series,
 'input_rows',jsonb_array_length(i),'output_rows',jsonb_array_length(o),
 'input_sha256',encode(sha256(convert_to(i::text,'UTF8')),'hex'),
 'output_sha256',encode(sha256(convert_to(o::text,'UTF8')),'hex'),
 'input_manifest_hash_matches',s.input_sha256=sha256(convert_to(i::text,'UTF8')),
 'output_manifest_hash_matches',s.output_sha256=sha256(convert_to(o::text,'UTF8')),
 'recorded_input_rows_match',s.input_rows=jsonb_array_length(i),'recorded_output_rows_match',s.output_rows=jsonb_array_length(o));
END;$fn$;
