 THEN RAISE EXCEPTION 'DAILY_EXACT_PARENT_DELEGATION_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=review_id AND event='ENGINEERING_INDEPENDENT_REVIEW_V5' AND details->>'assignment_event_id'='25097' AND details->>'review_subject'='DAILY_FINITE_CONTINUATION' AND details->>'status'='APPROVED' AND details->>'reviewer'='/root/daily_verifier/daily_review' AND details->>'review_sha256'='REVIEW_SHA256') THEN RAISE EXCEPTION 'DAILY_INDEPENDENT_REVIEW_REQUIRED';END IF;
