 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE e.details->>'claim_event_id'='26887' AND e.event ~ '(INTEGRAT|DEPLOY|COMPLET)') THEN RAISE EXCEPTION 'DAILY_EFFECTS_REQUIRE_RECONCILIATION';END IF;
 next_details:=a||jsonb_build_object('assignment_id','daily-practical-cohort-quality-verifier-v2-continuation-20261024','parent_assignment_event_id',25097,'parent_claim_event_id',26887,'delegated_by_executor','automation:6adc2c96db348191bca7cf4eacfdac32','not_after',least((c->>'claimed_at')::timestamptz+interval '30minutes',(SELECT admitted_until FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton),(SELECT deadline FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton)), 'independent_continuation_review_event_id',review_id,'maximum_elapsed_minutes',20,'maximum_tool_calls',70,'maximum_new_engineering_assignments',3,'cumulative_execution',jsonb_build_object('original_claim_started_at',c->>'claimed_at','original_maximum_elapsed_minutes',30,'original_maximum_tool_calls',100,'calls_reserved_as_used_before_successor',30,'remaining_tool_calls',70,'repair_iterations_used',0,'production_integrations_used',0),'continuation_reason','Original exact assignment admission ends before bounded reviewed implementation; same zero-provider scope, cumulative history and original deadline preserved. No production effects under parent claim.');
